PAGE = dict(
    slug='spire3',
    title='Pane::spire3',
    signature='Trace& Pane::spire3(Series z)\nTrace& Pane::spire3(Series y, Series z)\nTrace& Pane::spire3(Series x, Series y, Series z)\nTrace& Pane::spire3(Series x, Series y, Series z, Series c)',
    intro='Adds a **bar chart in three dimensions**: a vertical bar for each cell of a matrix `z`, standing on the grid of the coordinates with the height of the cell. It is the trace for a table of values over two categories, a histogram of two variables, or a surface shown as bars.\n\n`z` is a rank-2 matrix: its columns run along x and its rows along y. The calls differ in how much of the grid you give:\n\n| Call | Coordinates |\n|---|---|\n| `spire3(z)` | x and y are the indices 1, 2, 3, ... |\n| `spire3(y, z)` | y given, x the indices. |\n| `spire3(x, y, z)` | Both given. |\n| `spire3(x, y, z, c)` | Both given, and the bars are coloured by `c`, a matrix of the shape of `z`, instead of by their height. |\n\n`x` has as many entries as `z` has columns and `y` as many as it has rows, or both are full matrices of the shape of `z`. `z` must be rank 2 in every call: a rank-1 series throws.',
    parameters='**x**, **y** (`Series`-convertible, optional)\n    The coordinates of the columns and the rows.\n\n**z** (`Series`-convertible, rank 2)\n    The heights.\n\n**c** (`Series`-convertible, optional)\n    The values that colour the bars.',
    returns='`Trace&`\n    The new trace.',
    examples=[
        dict(id='z', text='Only the heights: one bar for each cell of a 3 by 3 matrix, standing at the positions 1, 2, 3 along x (the columns) and 1, 2, 3 along y (the rows).',
             code='auto fig = studio("spire3_z");\nauto& pane = fig.pane3("p");\nauto z = pluss::series::linspace(0.0, 4.0, 9, pluss::ScalarType::Float64).reshape({3, 3});\npane.spire3(z);\nfig.save_svg("figure.svg");'),
        dict(id='yz', text='With `y` given, the rows stand at those positions; the columns keep the positions 1, 2, 3.',
             code='auto fig = studio("spire3_yz");\nauto& pane = fig.pane3("p");\nauto z = pluss::series::linspace(0.0, 4.0, 9, pluss::ScalarType::Float64).reshape({3, 3});\npane.spire3(std::vector<double>{0, 5, 10}, z);\nfig.save_svg("figure.svg");'),
        dict(id='xyz', text='Both coordinates given: bars on a grid of your own spacing.',
             code='auto fig = studio("spire3_xyz");\nauto& pane = fig.pane3("p");\nauto z = pluss::series::linspace(0.0, 4.0, 9, pluss::ScalarType::Float64).reshape({3, 3});\npane.spire3(std::vector<double>{0, 1, 4}, std::vector<double>{0, 2, 3}, z);\nfig.save_svg("figure.svg");'),
        dict(id='color', text='A fourth argument colours the bars by another quantity, a matrix of the same shape as `z`. Here the bars are coloured by a matrix running the other way from their heights.',
             code='auto fig = studio("spire3_color");\nauto& pane = fig.pane3("p");\nauto z = pluss::series::linspace(0.0, 4.0, 9, pluss::ScalarType::Float64).reshape({3, 3});\nauto c = pluss::series::linspace(1.0, 0.0, 9, pluss::ScalarType::Float64).reshape({3, 3});\npane.spire3(std::vector<double>{0, 1, 2}, std::vector<double>{0, 1, 2}, z, c);\npane.scale_guide(true);\nfig.save_svg("figure.svg");'),
        dict(id='negative', text='Bars go down from zero for negative values.',
             code='auto fig = studio("spire3_negative");\nauto& pane = fig.pane3("p");\nauto z = pluss::make_series(std::vector<double>{2, -1, 3, -2, 1, 2, 0, 3, -3}, {3, 3});\npane.spire3(z);\nfig.save_svg("figure.svg");'),
        dict(id='errors', text='Inputs that cannot be drawn are refused when the trace is added, and the message names the method and the problem. The pane keeps the traces it had.',
             code='auto report = [](const char* what, auto&& call) {\n  auto fig = studio("spire3_errors");\n  auto& pane = fig.pane3("p");\n  try {\n    call(pane);\n    std::cout << what << ": accepted\\n";\n  } catch (const pluss::Error& e) {\n    std::cout << what << ": " << e.message() << "\\n";\n  }\n};\nreport("z is not a matrix", [](Pane& pane) { pane.spire3(std::vector<double>{1, 2, 3}); });\nreport("coordinates do not match z", [](Pane& pane) { auto z = pluss::series::linspace(0.0, 4.0, 9, pluss::ScalarType::Float64).reshape({3, 3}); pane.spire3(std::vector<double>{1, 2}, std::vector<double>{1, 2, 3}, z); });\nauto fig = studio("spire3_errors_out");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{0, 1}, std::vector<double>{0, 1}, std::vector<double>{0, 1});\nfig.save_svg("figure.svg");'),
        dict(id='wrong_pane', text='`spire3` needs a volumetric pane. On a planar pane it throws at once, naming the kind it needs, and nothing is added.',
             code='auto fig = studio("spire3_wrong_pane");\nauto& pane = fig.pane2("p");\ntry {\n  pane.spire3(pluss::series::linspace(0.0, 1.0, 4, pluss::ScalarType::Float64).reshape({2, 2}));\n} catch (const pluss::Error& e) {\n  std::cout << e.message() << "\\n";\n}\nstd::cout << "traces: " << pane.trace_count() << "\\n";\nfig.save_svg("figure.svg");'),
    ],
    notes='- Returns the new [`Trace&`](../trace/label.md); the reference stays valid for the life of the pane, and the style calls of the trace ([`label`](../trace/label.md), [`stroke`](../trace/stroke.md), [`width`](../trace/width.md), ...) chain off it.\n- The data is copied into the trace when it is added, so changing the vector afterwards does not change the figure.\n',
    see=['[`Pane::sheet`](sheet.md): the same data as a surface.', '[`Pane::lattice`](lattice.md): as a wire grid.', '[`Pane::columns`](columns.md): bars in the plane.'],
)
